	vector_set(node->cmd_vector, &bfd_profile_mult_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_profile_passive_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_profile_rx_cmd_vtysh);
